import { GLOSSARY, GLOSSARY_GROUPS } from "../src/app/core/glossary";

/**
 * The glossary page of the guide, made from the same entries as the Glossary view of the application
 * (`src/app/core/glossary.ts`), so the two cannot disagree. `docs/guide/glossary.md` is this text; a
 * test fails when the file is stale (`pnpm docs:glossary` writes it again).
 */
export function renderGlossary(): string {
  const parts = [
    "<!-- Generated from src/app/core/glossary.ts by `pnpm docs:glossary`. Do not edit this file. -->",
    "",
    "# Glossary",
    "",
    "The terms the CLI, the application and the MCP server use. The Glossary view of the application shows the same entries; both are made from one source.",
    "",
  ];
  for (const group of GLOSSARY_GROUPS) {
    parts.push(`## ${group}`, "");
    for (const entry of GLOSSARY.filter((e) => e.group === group)) {
      parts.push(`### ${entry.term}`, "", entry.long, "");
    }
  }
  return parts.join("\n");
}
